return {["scripts/actions/spells/black/pyrohelix.lua"]={["Path"]="scripts/actions/spells/black/pyrohelix.lua",["SHA256"]="a43c98e283b52fbdc42ccc3b79b6c2a21d889391b4ce440449dfab0e0dd7be6f",["Text"]="-----------------------------------\n-- Spell: Pyrohelix\n-- Deals fire damage that gradually reduces a target's HP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell) -- Gets nuke power and sets messages.\n\n    -- Can't apply if absorbed or nullified.\n    if damage > 0 then\n        local power    = utils.clamp(damage, 0, 9999)\n        local duration = xi.spells.enfeebling.calculateDuration(caster, target, spell:getID(), xi.effect.HELIX, xi.skill.ELEMENTAL_MAGIC)\n\n        target:addStatusEffect(xi.effect.HELIX, { power = power, duration = duration, origin = caster, tick = 10, tier = 1 })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/pyrohelix_ii.lua"]={["Path"]="scripts/actions/spells/black/pyrohelix_ii.lua",["SHA256"]="8a7a539dde84f981e398528cad7b027ba13aef69cc8b5a68edb441226fec5e20",["Text"]="-----------------------------------\n-- Spell: Pyrohelix II\n-- Deals fire damage that gradually reduces a target's HP.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local damage = xi.spells.damage.useDamageSpell(caster, target, spell) -- Gets nuke power and sets messages.\n\n    -- Can't apply if absorbed or nullified.\n    if damage > 0 then\n        local power    = utils.clamp(damage, 0, 9999)\n        local duration = xi.spells.enfeebling.calculateDuration(caster, target, spell:getID(), xi.effect.HELIX, xi.skill.ELEMENTAL_MAGIC)\n\n        target:addStatusEffect(xi.effect.HELIX, { power = power, duration = duration, origin = caster, tick = 10, tier = 2 })\n    end\n\n    return damage\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/quake.lua"]={["Path"]="scripts/actions/spells/black/quake.lua",["SHA256"]="30e191b88b525760c7e50b00bd96242c324d3c657d6672dfb522fbe4a675fb8e",["Text"]="-----------------------------------\n-- Spell: Quake\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    target:addStatusEffect(xi.effect.NINJUTSU_ELE_DEBUFF, { power = 30, duration = 10, origin = caster, icon = 0, subPower = xi.mod.WIND_MEVA })\n\n    return xi.spells.damage.useDamageSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/quake_ii.lua"]={["Path"]="scripts/actions/spells/black/quake_ii.lua",["SHA256"]="a6ce3a4eb1a4ef42c871e7935e196dce900082577f401325f2cd4d0e86459538",["Text"]="-----------------------------------\n-- Spell: Quake II\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    target:addStatusEffect(xi.effect.NINJUTSU_ELE_DEBUFF, { power = 30, duration = 10, origin = caster, icon = 0, subPower = xi.mod.WIND_MEVA })\n\n    return xi.spells.damage.useDamageSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/rasp.lua"]={["Path"]="scripts/actions/spells/black/rasp.lua",["SHA256"]="e553e95c626be75021404b986c1a2fa9b1077de0295105095ab3dcbc09bf71be",["Text"]="-----------------------------------\n-- Spell: Rasp\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enfeebling.useEnfeeblingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/retrace.lua"]={["Path"]="scripts/actions/spells/black/retrace.lua",["SHA256"]="955fde141dd94fc3c7c8d7fc505f3c5ae75483a25a3d0b79d2807fb86440d0a7",["Text"]="-----------------------------------\n-- Spell: Retrace\n-- Transports player to their Allied Nation. Can cast on allies.\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    if target:hasStatusEffect(xi.effect.MOUNTED) then\n        return xi.msg.basic.MAGIC_CANNOT_BE_CAST\n    end\n\n    if target:getCampaignAllegiance() == 0 then\n        return xi.msg.basic.MAGIC_CANNOT_BE_CAST\n    end\n\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enhancing.useTeleportSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/shock.lua"]={["Path"]="scripts/actions/spells/black/shock.lua",["SHA256"]="858daa0accb64cfcf942d2929acdb7ce7921d85425f564a512c7ace43a7a9c57",["Text"]="-----------------------------------\n-- Spell: Shock\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return 0\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.spells.enfeebling.useEnfeeblingSpell(caster, target, spell)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/black/shock_spikes.lua"]={["Path"]="scripts/actions/spells/black/shock_spikes.lua",["SHA256"]="d09d0c8101ed73e18ecc328bf0bba10f4e9c43a522dcd974fb2e2baa33387be0",["Text"]="-----------------------------------\n-- Spell: Shock Spikes\n-----------------------------------\n---@type TSpell\nlocal spellObject = {}\n\nspellObject.onMagic